-- 2262 🏋️ Exercises from the book "coaching-4-3-3-tactics-154-tactical-solutions-and-practices" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'coaching-4-3-3-tactics-154-tactical-solutions-and-practices');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('GK distribution and build-up through 3 zones', 'phase_of_play', 'overload', 'in_possession', 72, 72, 'Practice Examples for Build Up Play: 1', 'Massimo Lucchesi', 'Goalkeeper picks the right distribution for the opponent''s shape and the team builds up through the lines from the back.', 'Area from our goal line past halfway split into 3 equal horizontal zones (low, middle, high); our GK plus 10 outfield in 4-3-3 against 6 defenders (e.g. 2 forwards and 4 midfielders in a 4-2 shape).', 'GK restarts with a goal kick or throw; depending on the opponent''s shape the team adjusts (e.g. DM drops between the centre backs to form a back 3 and create a spare man in the low zone) and the GK finds the free player. The team then builds up as the coach instructs until the ball is played into the high zone, then restart from the GK.', 'Defenders press actively on the goal kick/throw, then only passively during the build-up.', 'Defenders become fully active, try to stop the build-up and score if they win the ball.', 'Read the opponent''s formation before distributing; create a numerical advantage at the back (e.g. 2(+1)v2, 5v4 in midfield).', '11v6 (GK + 10 v 6)', 17, 17, '3 equal zones from goal line to beyond halfway', NULL, NULL, NULL, true, true, true, NULL, 10),
  ('GK build-up 7(+GK)v6 to mini goals', 'phase_of_play', 'overload', 'in_possession', 73, 73, 'Practice Examples for Build Up Play: 2', 'Massimo Lucchesi', 'Build up from the back into the opponent''s half against a pressing unit, adapting to their formation.', 'Half a pitch with a full goal and GK; our GK, back 4 and 3 central midfielders against 6 opponents (e.g. 3-3, can be changed to 4-2 or 3-1-2); 3 mini goals on the halfway line.', 'GK chooses the distribution to suit the opponents'' shape (e.g. vs a 3-3 the LCM drops deep to make 4v3 and receive). The blues build up and try to score in a mini goal or dribble over halfway; the reds press as a unit and, on winning the ball, counter quickly at the big goal.', 'Blues score by finishing in any of the 3 mini goals on halfway or by dribbling across the halfway line; reds score in the big goal after a turnover.', 'Change the defenders'' formation (3-3, 4-2, 3-1-2) so the build-up solution must change.', 'Midfielder drops to create a numerical edge at the back; quick switches to the free side.', '7 (+GK) v 6', 14, 14, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 20),
  ('End-to-end 8v8+2 possession with keepers', 'positional_game', 'overload', 'in_possession', 74, 74, 'Practice Examples for Build Up Play: 3', 'Massimo Lucchesi', 'Build up from the back, keep possession and play positionally to move the ball from one keeper to the other.', 'Marked area of roughly two-thirds of a pitch with a goalkeeper outside each end; two teams of 8 outfield players plus 2 neutrals who act as the central midfielders for the team in possession.', 'Play starts from one GK; the team in possession sets up in a 4-3-3 with the 2 neutrals (11v8 including GK) and tries to string passes together and work the ball to the far GK, who then gives it to the other team, which attacks the opposite way with the same aims.', '1 point for 8 consecutive passes; 1 point for getting the ball from one GK to the other. If the defenders win the ball the roles simply swap and play continues.', NULL, 'Keep the 4-3-3 positional structure; use the neutrals as the free central players.', '8v8+2 neutrals + 2 GKs', 20, 20, NULL, NULL, NULL, NULL, false, true, true, NULL, 30),
  ('Find the forward, keep the ball 8v5', 'positional_game', 'overload', 'in_possession', 101, 101, 'Creating Phase Practice 1', NULL, 'Moving the ball to free the forward between the lines and keeping possession after the pass in.', 'Three zones across the pitch: 2 blue centre backs in zone 1, 3 central mids and 2 full backs in zone 2, 1 forward in a narrow zone 3 near the box; 5 reds (4 mids + 1 forward) roam zones 1 and 2.', 'Coach feeds a centre back; blues circulate to open a lane into the forward, who must receive in zone 3 and set it back to a teammate for a point, then play restarts from a centre back. If reds win it they try to dribble over the end line.', 'Blues locked in their zones; forward receiving in zone 3 and returning it = 1 point; reds dribbling over end line = 1 point and roles swap.', NULL, 'Forward keeps moving to open a passing line.', '8v5', 13, 13, NULL, NULL, NULL, NULL, false, false, true, NULL, 40),
  ('Keep-ball then one-touch attack 7v7+3', 'small_sided_game', 'overload', 'in_possession', 102, 102, 'Creating Phase Practice 2', NULL, 'Possession then attacking in behind, with collective pressing and transition for the defenders.', 'Pitch split into 3 zones; 7v7 plus 3 yellow neutrals (centre back and 2 wingers) in zone 1, both sides in 4-3-3 shape; 2 white defenders stay in zone 2 in front of a goal with GK.', 'Coach serves one team, which uses the 10v7 to string 6-8 passes in zone 1 for a point, then may leave the zone and attack the goal with one-touch play past the 2 white defenders. After the attack the coach serves the other team, which attacks the same goal.', '6-8 passes = 1 point before leaving zone 1; one-touch only once attacking; whites confined to zone 2; if the defending team wins it they must also complete 6-8 passes before attacking.', NULL, NULL, '7v7+3 neutrals+2 defenders+GK', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Break the midfield line through the middle', 'phase_of_play', 'opposed', 'in_possession', 103, 103, 'Creating Phase Practice 3', NULL, 'Circulating for width and passing forward to finish through central areas.', 'Half a pitch in 2 zones: blues have 2 full backs in side channels and 3 central mids in zone 1 plus 1 forward in zone 2; 4 red midfielders in the middle of zone 1; 4 mannequin defenders and a GK in zone 2.', 'Coach serves; blues find a lane to the forward (who may shift sideways only), he receives behind the red mids and sets back for a point, then blues attack centrally to score. Reds may track back.', 'Set-back after receiving = 1 point; goal = 1 point; reds winning it score by dribbling past halfway (1 point).', NULL, NULL, '6v4 + mannequins + GK', 11, 11, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Circulate wide to the wingers 8v4', 'phase_of_play', 'overload', 'in_possession', 104, 104, 'Creating Phase Practice 4', NULL, 'Using width to switch, pass forward and finish with set combinations.', 'As the previous practice plus 2 blue wingers starting in zone 2 with the forward; 4 red midfielders, 4 mannequins and GK.', 'Coach serves; blues move it to find a winger or the forward behind the red mids, who sets back for a point. Then finish by switching to the far winger who crosses for the forward, or by the forward laying off to a runner who goes through the middle or out wide.', 'Set-back = 1 point; goal = 1 point; reds dribbling past halfway on a win = 1 point.', NULL, 'Stress width from the wingers.', '8v4 + mannequins + GK', 13, 13, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Circulate wide to the wingers 10v6', 'phase_of_play', 'overload', 'in_possession', 105, 105, 'Creating Phase Practice 5', NULL, 'Building through width and depth from the centre backs and finishing with combinations against more pressure.', 'Practice 4 set-up with 2 blue centre backs and 2 red forwards added; reds in a shape such as 4-4-2 (adapt to next opponent); mannequins and GK in zone 2.', 'Coach serves; blues find a winger or forward behind the reds'' midfield for a set-back point, then finish via far-winger cross or forward lay-off to a midfield runner.', 'Full back may not pass straight to the winger on his side; points as in Practice 4.', NULL, NULL, '10v6 + mannequins + GK', 17, 17, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 80),
  ('10v11 switch and combine game', 'conditioned_game', 'opposed', 'in_possession', 106, 106, 'Creating Phase Practice 6', NULL, 'Ball circulation, forward passing and free choice of finishing combinations against a full defence.', 'Practice 5 set-up with 4 live red defenders replacing the mannequins (reds e.g. 4-4-2 plus GK); 2 small goals on the halfway area for the reds to counter into.', 'Coach serves the blues, who build and choose their own combinations to break through and score against a fully contested back line; reds win it and counter.', NULL, NULL, 'Players pick from the combinations used earlier in the section.', '10v11', 21, 21, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Two-sided 4-3-3 pattern play to finish', 'combination', 'unopposed', 'in_possession', 144, 144, 'Finishing Phase Practice 1', NULL, 'Pattern play with lay-offs, crossing and finishing from 4-3-3 positions.', 'Half pitch split vertically, 5-6 players on each side in rough 4-3-3 positions, balls with the centre backs, GK in goal.', 'Both halves run a pattern at once. Left: centre back lofts to the winger, who sets for the overlapping left back, who finds the forward, who lays off for the central mid to shoot from outside the box. Right: centre back to holding mid to the inverted winger, lay-off to the central mid, pass for the overlapping right back who crosses for the forward.', NULL, 'Swap in other combinations from the chapter''s tactical examples.', NULL, '10-12 + GK', 11, 13, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Keep-ball then runs in behind', 'positional_game', 'overload', 'in_possession', 145, 145, 'Finishing Phase Practice 2', NULL, 'Possession and timing passes and runs in behind a back line to finish.', 'Half pitch: large zone 1 the width of the box, small zone 2 full width in front of the area; 4v4 + 2 yellow neutrals (centre back and forward roles) in zone 1; 2 neutral wingers outside zone 1; 3 red defenders in zone 2; GK.', 'Coach serves; blues with neutrals string 8-10 passes in zone 1, then release a neutral winger running in behind the 3 reds and finish quickly with support runs.', 'Red defenders may intercept but cannot leave zone 2; if reds win it in zone 1, roles reverse.', NULL, 'Finish fast; others run to support.', '4v4+4 neutrals+3 defenders+GK', 16, 16, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 110),
  ('5v5 with neutral wide crossers', 'small_sided_game', 'overload', 'in_possession', 146, 146, 'Finishing Phase Practice 3', NULL, 'Using width to get crosses in and finish.', 'Main middle zone with two full-size goals and GKs, 5v5 (holding mid, 2 central mids, 2 wingers, forward - no centre backs); a side zone on each flank with a yellow neutral full back.', 'Start from coach or GK; team in possession uses the 7v5 to get the ball wide quickly so the neutrals cross for finishes; constant crossing.', 'Neutral full backs only play for the team with the ball; on a turnover roles reverse.', NULL, NULL, '5v5+2 neutrals+2 GKs', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Three-team winner-stays-on shooting game', 'finishing', 'opposed', 'in_possession', 147, 147, 'Finishing Phase Practice 4', NULL, 'Finishing quickly in the box in match-like situations.', 'Area twice the size of the penalty box with a goal and GK at each end; 2 teams play inside, a third team of 6 waits outside.', 'High-tempo game, shoot as soon as there is space. First goal wins; the team that concedes leaves and the waiting team comes on straight away.', 'First goal wins, winner stays on.', NULL, 'Shoot early when a gap opens.', '3 teams of 6 + 2 GKs', 20, 20, 'double penalty box', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Blocked attack: recycle and restart', 'phase_of_play', 'passive', 'in_possession', 148, 148, 'Finishing Phase Practice 5', NULL, 'Reading when attacking options are blocked, supporting, keeping the ball and resetting or starting a new attack.', 'Blues in 4-3-3 minus GK and centre backs; reds GK plus 7 outfield (shape to suit next opponent). White boxes in the wide areas each with a blue full back and 2 passive reds; yellow boxes inside them for the central mids; small goals at halfway.', 'Coach passes into a white box; the full back either plays into the yellow box for the central mid or back to the holding mid. When the mid receives, one red may enter to press, and he chooses: new attack (e.g. 1-2 with winger and ball in behind for the forward) or back to the holding mid to reset. Then repeat on the other side.', 'Two reds in white box only passive; one red may press once the ball enters the yellow box.', NULL, 'Always have a support player behind to recycle to.', '8v8 incl. GK', 16, 16, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('High press 6v7 to win ball in front third', 'defending', 'opposed', 'out_of_possession', 169, 169, 'Defensive Phase Practice 1', NULL, 'Pressing as a unit to win the ball high up and attack goal quickly.', 'Half pitch split into two zones; big goal with keeper at one end, three mini goals at the halfway end. Reds: back four plus three midfielders; blues: three central mids, two wingers and a forward.', 'Red keeper starts, reds build up through the blue press and try to score in a mini goal. Blues press to regain in zone 1 and break fast on the big goal; once blues win it only the four red defenders defend.', 'Win in zone 1 and score within 5 seconds = 2 points. Win in zone 2 = must make 7 passes before scoring for 1 point.', 'Defensive Phase Practice 2 extends to 10v10 on a larger area.', 'Press high to avoid the 7-pass rule; quick fast break after the regain.', '6v7 (+GK)', 14, 14, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('High press 10v10 with five mini goals', 'defending', 'opposed', 'out_of_possession', 170, 170, 'Defensive Phase Practice 2', NULL, 'Whole-team pressing in the front zone to win the ball and finish quickly.', 'Larger area, all 20 outfield players; big goal with keeper at one end, five mini goals for the reds at the other. Reds set up as a 4-4-2 (or the next opponent''s shape), blues in 4-3-3.', 'Reds build up from their keeper aiming at any of the five mini goals; blues press to win it high in zone 1 and attack the big goal.', 'Same as Practice 1: win in zone 1 and score fast = 2 points; win in zone 2 needs 7 passes before a 1-point goal.', NULL, 'More mini goals makes red scoring easier, so the blue press must be sharper and higher.', '10v10 (+GK)', 21, 21, NULL, NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Compact block then swarm the ball', 'defending', 'opposed', 'out_of_possession', 171, 171, 'Defensive Phase Practice 3', NULL, 'Staying compact in our half and reacting quickly to crowd the ball when opponents play between the lines.', 'Our half of the pitch with a keeper in the big goal and three mini goals on the halfway line; a highlighted zone in front of the box between our midfield and back lines. Blues in 4-3-3, reds in the next opponent''s shape.', 'Reds try to play through the blue block and score past the keeper. Blues defend compactly, blocking lanes and covering support players; if reds get into the highlighted zone, blues collapse onto the ball to win it. Blues regaining the ball counter into a mini goal.', NULL, NULL, 'Short distances between lines; block lanes and mark the support players; fast reaction once the ball goes between the lines.', '11v10 (team v team)', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Twin 5v2 rondos in team roles', 'rondo', 'overload', 'in_possession', 188, 188, 'Session 1: Practice 1', NULL, 'Passing, receiving and keeping the ball as building blocks for build-up play.', 'Two 15 x 10 grids. Top: CB at the base, full backs and wingers on the sides. Bottom: CB at the base, LCM and RCM on the sides, forward at the top, DM in the middle. Two defenders in each grid.', 'Five blues keep the ball against two yellows trying to win it; intensity builds through the practice.', NULL, 'Raise the intensity progressively.', NULL, '5v2 x2', 14, 14, '15 x 10 yards', 13.7, 9.1, NULL, false, false, false, NULL, 180),
  ('10v10 zonal possession, 10 passes', 'possession', 'opposed', 'in_possession', 189, 189, 'Session 1: Practice 2', NULL, 'Circulating the ball with movement and support to rehearse build-up.', 'One main zone with a thinner end zone at each end. In the main zone each team has back four, DM and two central mids; in the end zones each team has two wingers and a forward. Players stay in their zones.', 'Coach serves to one team, who try to string 10 passes using their three end-zone players. If the other team wins it, roles swap and they go for 10 passes.', 'Players stay in their own zones; aim is 10 consecutive passes.', NULL, 'End-zone players move well and open their body to receive. Give rest breaks - pressing side works very hard.', '10v10', 20, 20, NULL, NULL, NULL, NULL, false, false, false, NULL, 190),
  ('4-3-3 build-up pattern past mannequins', 'combination', 'unopposed', 'in_possession', 190, 190, 'Session 1: Practice 3', NULL, 'Rehearsing a set build-up pattern from the back including a vertical entry pass through midfield.', 'Full pitch, nine players in 4-3-3 positions (back four, DM, two CMs, two wingers, forward) and six mannequins as opponents.', 'LCB to DM, DM to RCB, RCB to RB, RB drives a pass to the RW coming inside, RW sets back to the RCM, RCM finds the forward, who lays it back to the start. Then repeat to the other side from RCB.', NULL, 'Swap in other build-up patterns from the book''s tactical chapters.', NULL, '9 + 6 mannequins', 9, 9, 'full pitch', NULL, NULL, NULL, false, false, true, NULL, 200),
  ('Build-up through three zones to goal', 'phase_of_play', 'opposed', 'in_possession', 191, 191, 'Session 1: Practice 4', NULL, 'Playing out from the back under pressure and finishing, with transitions both ways.', 'Pitch split into three zones with a goal and keeper at each end. Blues in 4-3-3, reds in the next opponent''s formation.', 'Blue keeper starts; a CB can drop into the first zone free. Blues work the ball through the press into the third zone, where they start 3v4 but the LCM may push up to level it, then shoot. Reds who win it break fast; blues counter-press after losing it.', 'Blue goal = 1 point. Red goal = 1, or 2 if within 6-8 seconds of winning it. Blues regaining after a loss = 1 point. Restart from blue keeper when ball goes out.', NULL, NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Three-team rondo with aerial switch', 'rondo', 'overload', 'in_possession', 193, 193, 'Session 2: Practice 1', NULL, 'Keeping the ball under pressure then switching it over a middle zone.', 'Two 15 x 10 end zones with a 15 x 5 zone between them. Three teams of 5-7 (example: 5 each); one team in each end zone, defenders in the middle.', 'Coach serves into an end zone; that team keeps it against two middle players who step in. After 6 passes they lift a ball over the middle to the team at the other end, where two middle players then press. If the pressers win it, they swap roles with the team that lost it.', '6+ consecutive passes then a pass to the far zone = 1 point; most points wins.', NULL, NULL, '3 teams of 5-7 (5v2 in each end)', 15, 21, 'two 15 x 10 zones + 15 x 5 middle', 32.0, 13.7, NULL, false, false, true, NULL, 220),
  ('Diamond drill: check away, play forward', 'passing_unopposed', 'unopposed', 'in_possession', 194, 194, 'Session 2: Practice 2', NULL, 'Passing, checking away from a marker before receiving, and quick combinations to play in behind.', 'Total area 15 x 25 split into two halves; in each a group of 5 with four players in a diamond (A, B, C, D) and two mannequins as opponents.', 'A to B, who checks away from his mannequin first; B plays D first time and spins inside for the return; D sets to B; C checks away and runs forward and B plays him in. Players rotate one spot (A to B to C to D to A).', NULL, 'Run other combinations in both halves.', 'Check away from the marker before showing; one-touch where possible.', '2 groups of 5', 10, 10, '15 x 25 yards', 22.9, 13.7, NULL, false, false, true, NULL, 230),
  ('Four-zone game: open up and play behind', 'positional_game', 'overload', 'in_possession', 195, 195, 'Session 2: Practice 3', NULL, 'Possession, forward passing and support to create an opening and play in behind.', 'Four zones across the pitch, goals and keepers at both ends. Two teams of 7 plus 3 neutrals (DM, LCM, RCM).', 'Keeper starts; blues have a 7v3 edge across zones 1-2 with the neutrals and look for an opening to pass into zone 3. Once in, the LCM and RCM neutrals may join for a 5v4 and the blues try to play in behind and score. Then restart from the red keeper with roles swapped.', 'Reds stay in zone 3. Score within 6 seconds = 2 points. Defending team breaks fast if it wins the ball.', NULL, NULL, '7v7 +3 neutrals +2 GKs', 19, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 240),
  ('10v7 positional attack to play behind', 'phase_of_play', 'overload', 'in_possession', 196, 196, 'Session 2: Practice 4', NULL, 'Using a numerical advantage in a positional attack to get in behind and score.', 'Pitch in two zones: zone 1 (build-up) and zone 2 (in behind, near the goal). A full blue team against seven red outfielders in 4-3 plus a keeper.', 'Blue keeper starts; blues use width and the extra men to build and play the ball into zone 2, then finish. Reds stay compact and counter-attack if they win it. Restart from the blue keeper after each attack.', 'Reds must stay in zone 1 and may not drop into zone 2 to defend.', 'Blues can rehearse any build-up/attacking combination from the book.', 'Exploit width and the spare men.', '10v7 (+GKs)', 19, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 250)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'coaching-4-3-3-tactics-154-tactical-solutions-and-practices') b;
INSERT INTO schema_migrations (filename) VALUES ('2262-exercises-book-coaching-4-3-3-tactics-154-tactical-solutions-and-practices.sql') ON CONFLICT DO NOTHING;
COMMIT;
